// ============================================================
// ReLU Backward 算子 op_kernel
// grad_input = grad_output * (self > 0)
// 双输入单输出 elementwise 算子
// ============================================================

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelReluBackward {
public:
    __aicore__ inline KernelReluBackward() {}

    __aicore__ inline void Init(GM_ADDR grad, GM_ADDR self, GM_ADDR output,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            gradGm.SetGlobalBuffer((__gm__ T *)grad + offset, formerLength);
            selfGm.SetGlobalBuffer((__gm__ T *)self + offset, formerLength);
            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            gradGm.SetGlobalBuffer((__gm__ T *)grad + offset, tailLength);
            selfGm.SetGlobalBuffer((__gm__ T *)self + offset, tailLength);
            outputGm.SetGlobalBuffer((__gm__ T *)output + offset, tailLength);
        }

        this->tileLength = tileLength;

        pipe.InitBuffer(inQueueGrad, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueSelf, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueue, BUFFER_NUM, tileLength * sizeof(T));

        // FP32临时缓冲区: 升精度计算需要
        // selfFp32 + gradFp32 + calcFp32
        if constexpr (sizeof(T) != sizeof(float)) {
            pipe.InitBuffer(tempBufSelf, tileLength * sizeof(float));
            pipe.InitBuffer(tempBufGrad, tileLength * sizeof(float));
            pipe.InitBuffer(tempBufCalc, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        // 搬入 grad_output
        AscendC::LocalTensor<T> gradLocal = inQueueGrad.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(gradLocal, gradGm[progress * this->tileLength], copyParams);
        inQueueGrad.EnQue(gradLocal);

        // 搬入 self
        AscendC::LocalTensor<T> selfLocal = inQueueSelf.AllocTensor<T>();
        AscendC::DataCopyPad(selfLocal, selfGm[progress * this->tileLength], copyParams);
        inQueueSelf.EnQue(selfLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> gradLocal = inQueueGrad.DeQue<T>();
        AscendC::LocalTensor<T> selfLocal = inQueueSelf.DeQue<T>();
        AscendC::LocalTensor<T> outputLocal = outQueue.AllocTensor<T>();

        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32 路径: 直接计算
            AscendC::LocalTensor<float> maskFp32 = outQueue.AllocTensor<float>();
            AscendC::Relu(maskFp32, selfLocal, curTileLength);               // max(0, self)
            AscendC::Sgn(maskFp32, maskFp32, curTileLength);                 // 1 if self>0, 0 otherwise
            AscendC::Mul(outputLocal, maskFp32, gradLocal, curTileLength);   // gated gradient
            outQueue.FreeTensor(maskFp32);
        } else {
            // FP16/BF16 路径: 升精度到 FP32 计算
            AscendC::LocalTensor<float> selfFp32 = tempBufSelf.Get<float>();
            AscendC::LocalTensor<float> gradFp32 = tempBufGrad.Get<float>();
            AscendC::LocalTensor<float> maskFp32 = tempBufCalc.Get<float>();

            // 升精度 Cast
            AscendC::Cast(selfFp32, selfLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(gradFp32, gradLocal, AscendC::RoundMode::CAST_NONE, curTileLength);

            // FP32 计算
            AscendC::Relu(maskFp32, selfFp32, curTileLength);                 // max(0, selfFp32)
            AscendC::Sgn(maskFp32, maskFp32, curTileLength);                  // 1 if >0, 0 otherwise (in-place)
            AscendC::Mul(maskFp32, maskFp32, gradFp32, curTileLength);        // mask = mask * grad (in-place)

            // 降精度 Cast
            AscendC::Cast(outputLocal, maskFp32, AscendC::RoundMode::CAST_RINT, curTileLength);
        }

        outQueue.EnQue<T>(outputLocal);
        inQueueGrad.FreeTensor(gradLocal);
        inQueueSelf.FreeTensor(selfLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> outputLocal = outQueue.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(outputGm[progress * this->tileLength], outputLocal, copyParams);
        outQueue.FreeTensor(outputLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueGrad;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueSelf;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBufSelf;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBufGrad;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tempBufCalc;
    AscendC::GlobalTensor<T> gradGm;
    AscendC::GlobalTensor<T> selfGm;
    AscendC::GlobalTensor<T> outputGm;
    int64_t blockLength;
    int64_t tileLength;
};

extern "C" __global__ __aicore__ void relu_backward(GM_ADDR grad, GM_ADDR self, GM_ADDR output,
                                                     int64_t formerNum, int64_t formerLength,
                                                     int64_t tailLength, int64_t tileLength,
                                                     int64_t dtypeSize, int64_t isBf16)
{
    if (dtypeSize == 2) {
        if (isBf16) {
            KernelReluBackward<AscendC::bfloat16_t> op;
            op.Init(grad, self, output, formerNum, formerLength, tailLength, tileLength);
            op.Process();
        } else {
            KernelReluBackward<half> op;
            op.Init(grad, self, output, formerNum, formerLength, tailLength, tileLength);
            op.Process();
        }
    } else {
        KernelReluBackward<float> op;
        op.Init(grad, self, output, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
