// ============================================================
// ReLU Backward 算子 op_host
// Host 端: Tiling 计算 + kernel 启动
// ============================================================

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_relu_backward.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor relu_backward(const at::Tensor &grad_output, const at::Tensor &self)
{
    // ---- 输入校验 ----
    TORCH_CHECK(grad_output.device().is_privateuseone(), "grad_output must be on NPU");
    TORCH_CHECK(self.device().is_privateuseone(), "self must be on NPU");
    TORCH_CHECK(grad_output.dtype() == self.dtype(),
                "grad_output and self must have the same dtype, got ",
                grad_output.dtype(), " vs ", self.dtype());
    TORCH_CHECK(grad_output.sizes() == self.sizes(),
                "grad_output and self must have the same shape, got ",
                grad_output.sizes(), " vs ", self.sizes());
    TORCH_CHECK(grad_output.is_contiguous(), "grad_output must be contiguous");

    auto dtype = grad_output.scalar_type();
    TORCH_CHECK(dtype == at::kHalf || dtype == at::kFloat || dtype == at::kBFloat16,
                "relu_backward: only float16, bfloat16, and float32 are supported, got ", dtype);

    // ---- 创建输出 ----
    at::Tensor output = at::empty_like(grad_output);

    int64_t totalLength = grad_output.numel();
    if (totalLength == 0) {
        return output;
    }

    int64_t dtypeSize = grad_output.element_size();

    // ---- 获取硬件参数 ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block 级 tiling (核间切分, Cache Line 512B 对齐) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB 级 tiling (核内切分, 32B 对齐) ----
    bool isFp16OrBf16 = (dtype == at::kHalf || dtype == at::kBFloat16);
    int64_t bufferCoefficient;
    if (isFp16OrBf16) {
        bufferCoefficient = 24;  // FP16/BF16: 24
    } else {
        bufferCoefficient = 32;  // FP32: 32
    }

    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    if (dtypeSize == 0) { dtypeSize = 1; }
    int64_t alignElements = 32 / dtypeSize;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;

    // ---- 准备左值参数, Launch kernel ----
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    int64_t isBf16 = (dtype == at::kBFloat16) ? 1 : 0;

    EXEC_KERNEL_CMD(relu_backward, blockDim,
                    grad_output, self, output,
                    formerNum, formerLength, tailLength, tileLength, dtypeSize, isBf16);

    return output;
}

}  // namespace ascend_kernel
